import {PICKAXE_STYLES} from './pickaxe-style.js';
import {ART_TYPES,generateAsset,assetToSvg,assetSvgBody,drawAsset} from './art-kit.js';
import {PALETTE,P} from './palette.js';
import {createState,startRun,generateRoom} from './core.js';
import {World} from './world.js';
const $=id=>document.getElementById(id);
const names={zag:'Zag, o Apostador',drill:'Broca da Fortuna',ticket:'Passe do Zag',boss:'Chefe',crystal:'Quartzo',rock:'Rocha',miner:'Explorador',pickaxe:'Picareta',gardener:'Ouriço de cristal',hedgehog:'Ouriço de cristal',slime:'Gosma ácida',bat:'Morcego sônico',golem:'Guardião',tree:'Árvore de ecos',bush:'Arbusto',molehill:'Toca de âmbar',mushroom:'Cogumelo',fossil:'Fóssil',lava:'Magma',forge:'Forja',board:'Quadro de missões',shrine:'Oficina estelar',lift:'Elevador',well:'Poço dos desejos',gramophone:'Vitrola',tent:'Tenda',crate:'Suprimentos',lantern:'Lampião',campfire:'Fogueira',potion:'Poção de cura',shield:'Escudo'};
const entries=[...PICKAXE_STYLES.map((style,variant)=>({type:'pickaxe',variant,name:'Picareta '+style.name+' · NV. '+style.level})),...[0,1,2,3,4,5].map(variant=>({type:'boss',variant,name:['Rei Geodo','Matriarca Raiz','Titã Fóssil','Boss Místico','Soberano Micelial','Rei das Tocas'][variant]})),...[0,1,2,3].map(variant=>({type:'crystal',variant,name:['Quartzo','Rubi','Topázio','Esmeralda'][variant]})),...ART_TYPES.filter(t=>t!=='crystal'&&t!=='boss'&&t!=='pickaxe'&&t!=='gardener').map(type=>({type,variant:0,name:names[type]}))];
let seed=1208,biome=0,selected=0,cave=false,state,category='all';
const groups={village:['miner','forge','well','lift','board','tree','shrine','zag','tent','crate','lantern','campfire','gramophone'],creatures:['slime','bat','hedgehog','golem','boss'],resources:['molehill','crystal','rock','mushroom','bush','fossil','lava'],equipment:['pickaxe','potion','shield','ticket','drill']};
const world=new World($('scene'));world.setSoft(true);
$('palette').innerHTML=PALETTE.map(color=>`<span class="swatch" style="background:${color}" title="${color}"></span>`).join('');
const model=i=>generateAsset(entries[i].type,{seed:seed+i*17,variant:entries[i].variant,biome});
function spotlight(){const entry=entries[selected];$('spotlight').innerHTML=assetToSvg(model(selected));$('assetName').textContent=entry.name;for(const b of $('gallery').querySelectorAll('button'))b.setAttribute('aria-pressed',String(Number(b.dataset.index)===selected));}
function scene(){state=createState(seed);if(cave){startRun(state);state.run.floor=biome*5+1;generateRoom(state);}world.place(state);world.resize();world.draw(state,0,0,null,null,true);$('showBase').setAttribute('aria-pressed',String(!cave));$('showCave').setAttribute('aria-pressed',String(cave));}
function render(){seed=Math.min(4294967295,Math.max(0,Math.floor(Number($('seed').value)||0)));$('seed').value=seed;biome=Number($('biome').value);const visible=entries.map((e,i)=>({...e,i})).filter(e=>category==='all'||groups[category].includes(e.type));if(!visible.some(e=>e.i===selected))selected=visible[0].i;$('gallery').innerHTML=visible.map((e)=>`<button class="asset" data-index="${e.i}" aria-label="${e.name}" aria-pressed="${selected===e.i}">${assetToSvg(model(e.i))}<span>${e.name.toUpperCase()}</span></button>`).join('');$('pieceCount').textContent=visible.length+' PEÇAS · ESCOLHA UMA';spotlight();scene();$('status').textContent='Variação '+seed+' · HEPT32';}
$('artGroups').addEventListener('click',e=>{const button=e.target.closest('[data-group]');if(!button)return;category=button.dataset.group;for(const b of $('artGroups').querySelectorAll('button'))b.setAttribute('aria-pressed',String(b===button));render();});
$('gallery').addEventListener('click',e=>{const b=e.target.closest('button[data-index]');if(b){selected=Number(b.dataset.index);spotlight();}});
$('seed').addEventListener('change',render);$('biome').addEventListener('change',render);
$('regenerate').addEventListener('click',()=>{$('seed').value=(seed+1)>>>0;render();});
$('showBase').addEventListener('click',()=>{cave=false;scene();});$('showCave').addEventListener('click',()=>{cave=true;scene();});
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('status').textContent='Arquivo preparado: '+name;}
$('download').addEventListener('click',()=>download(new Blob([assetToSvg(model(selected))],{type:'image/svg+xml'}),`gemventure-${entries[selected].type}-${seed}.svg`));
$('png').addEventListener('click',()=>{const c=document.createElement('canvas');c.width=400;c.height=440;const a=model(selected);drawAsset(c.getContext('2d'),a.type,200,384,400,a);c.toBlob(blob=>{if(blob)download(blob,`gemventure-${a.type}-${seed}.png`);});});
$('sheet').addEventListener('click',()=>{const rows=Math.ceil(entries.length/5),height=rows*165+95;const body=entries.map((e,i)=>{const x=25+(i%5)*150,y=85+Math.floor(i/5)*165;return `<g transform="translate(${x+20} ${y})">${assetSvgBody(model(i))}</g><text x="${x+70}" y="${y+132}" text-anchor="middle" fill="${P.silver}" font-family="sans-serif" font-size="11">${e.name}</text>`;}).join('');const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="800" height="${height}" viewBox="0 0 800 ${height}"><rect width="800" height="${height}" fill="${P.ink}"/><text x="40" y="40" fill="${P.lemon}" font-family="sans-serif" font-weight="bold" font-size="24">GEMVENTURE / HEPT32</text><text x="40" y="62" fill="${P.silver}" font-family="sans-serif" font-size="11">ENDESGA · VARIAÇÃO ${seed} · LUZ SUPERIOR ESQUERDA</text>${body}</svg>`;download(new Blob([svg],{type:'image/svg+xml'}),`gemventure-colecao-${seed}.svg`);});
new ResizeObserver(()=>{if(state){world.resize();world.draw(state,0,0,null,null,true);}}).observe($('scene'));
render();document.fonts.ready.then(scene);
